                    cur = node
                    for _ in range(cycle_len - 1):
                        cycle_nodes.append(cur)
                        cur = parent[cur]
                    cycle_nodes.append(cur)
                    cycle_nodes.append(node)
                    return f"2\n{len(cycle_nodes)}\n{' '.join(map(str, cycle_nodes))}\n"

    # Fall back to finding dependent set with different approach
    # BFS layering
