                if not visited2[neighbor]:
                    visited2[neighbor] = True
                    next_layer.append(neighbor)
        layer += 1
        layer_nodes = next_layer

    # Count nodes per layer
    layer_indices = []
    depth_layer = [0] * (n + 1)
    cur_layer = 0
    cur_nodes = [1]
    visited_bfs = [False] * (n + 1)
    visited_bfs[1] = True

    while cur_nodes:
