        next_nodes = []
        for node in cur_nodes:
            for neighbor in adj[node]:
                if not visited_bfs[neighbor]:
                    visited_bfs[neighbor] = True
                    depth_layer[neighbor] = cur_layer + 1
                    next_nodes.append(neighbor)
        cur_layer += 1
        cur_nodes = next_nodes

    # For layers with many nodes, they might contain independent sets
    all_nodes = []
    for i in range(1, n + 1):
        all_nodes.append((i, color[i]))

    if len(all_nodes) >= target:
        result = []
        for i in range(len(all_nodes)):
            if len(result) >= target:
                break
            result.append(str(all_nodes[i][0]))
        return f"1\n{' '.join(result)}\n"

    return f"1\n" + " ".join([str(i) for i in range(1, target + 1)])
