import sys

def solution(input_text):
    lines = input_text.strip().split('\n')
    if not lines:
        return '0\n'
    n, m = map(int, lines[0].split())
    matrix = lines[1:n + 1]  # Matrix rows

    beautiful_count = 0

    # For each submatrix, check if each row and column can form a palindrome
    # A string can form a palindrome iff at most one character has odd frequency

    # Precompute row-wise character counts modulo 2 using bitmask
    # Since characters are 'a'-'z', we can use 26-bit integers
    # bit i represents character ('a' + i)

    # row_mask[i][j] = bitmask of characters in row i from column 0 to j-1
    row_mask = [[0] * (m + 1) _ for _ in range(n)]
    for i in range(n):
        mask = 0
        for j in range(m):
            mask ^= 1 << (ord(matrix[i][j]) - ord('a'))
            row_mask[i][j + 1] = mask

    # col_mask[i][j] = bitmask of characters in column j from row 0 to i-1
    col_mask = [[0] * (m + 1) _ for _ in range(n)]
    for j in range(m):
        mask = 0
        for i in range(n):
            mask ^= 1 << (ord(matrix[i][j]) - ord('a'))
            col_mask[i + 1][j] = mask

    # Precompute for each pair of columns, which rows have odd counts for certain chars
    # Actually let's do forward checking: for each (r1, c1, r2, c2) check if valid

    # Better approach: for submatrix [r1..r2][c1..c2], check each row and column

    for r1 in range(n):
        for c1 in range(m):
            # Store which rows from r1 to r2 can form palindromes when intersected with [c1..c2]
            # Actually let's just check directly - might be fast enough since n, m <= 250

            for r2 in range(r1, n):
                for c2 in range(c1, m):
                    # Check each row in submatrix
                    ok = True
                    for i in range(r1, r2 + 1):
                        row_mask_range = row_mask[i][c2 + 1] ^ row_mask[i][c1]
                        if cnt_odd_bitwise(row_mask_range) > 1:
                            ok = False
                            break
                    if not ok:
                        continue

                    # Check each column in submatrix
                    for j in range(c1, c2 + 1):
                        col_mask_range = col_mask[r2 + 1][j] ^ col_mask[r1][j]
                        if cnt_odd_bitwise(col_mask_range) > 1:
                            ok = False
                            break
                    if ok:
                        beautiful_count += 1

    return str(beautiful_count) + '\n'


def cnt_odd_bitwise(mask):
    # Count bits that are set (characters with odd frequency in this range)
    return bin(mask).count('1')
