                before_constraints[b] = before_constraints.get(b, set()) | {a}
                after_constraints[a] = after_constraints.get(a, set()) | {b}
            else:  # RIGHT
                before_constraints[a] = before_constraints.get(a, set()) | {b}
                after_constraints[b] = after_constraints.get(b, set()) | {a}

        # Check for cycles
