def digits_from_1_to(n):
    if n <= 0:
        return 0
    total = 0
    d = 1
    start = 1
    while start <= n:
        end = min(n, 10**d - 1)
        cnt = end - start + 1
        total += cnt * d
        start = end + 1
        d += 1
    return total

