    k = int(parts[2])

    # Total arrangements (choose positions for the n people with 10 euro)
    total_arrangements = combinations(n + m, n)

    if total_arrangements == 0:
        return "0\n"

    if m == 0:
        # No one needs change, always smooth
        return "1\n"

    if k >= m:
        # Start with enough change for all 20 euro customers
        return "1\n"

    if n == 0:
        # Only 20 euro customers, need at least m initial 10 euro banknotes
        if k >= m:
            return "1\n"
        else:
            return "0\n"

    # Count invalid paths using reflection principle
    # Invalid path = one where at some point remaining change drops below 0
    # Using the formula: invalid = C(n + m, n - k - 1)

    # The number of paths that go below zero at some point
    invalid_count = combinations(n + m, n - k - 1)

    valid_count = total_arrangements - invalid_count

    if valid_count < 0:
        valid_count = 0
        invalid_count = total_arrangements

    probability = valid_count / total_arrangements

