    m = int(lines[2])
    actions = []
    for i in range(m):
        parts = lines[3+i].split()
        actions.append((parts[0], int(parts[1])))

    from functools import lru_cache

    # Sort strengths in descending order to normalize heroes with same strength
    # Heroes with same strength are interchangeable, so we can just use sorted values
    available = tuple(sorted(strengths, reverse=True))

    @lru_cache(maxsize=None)
    def solve(action_idx, available):
        """Return Team 1's advantage (T1_sum - T2_sum) from this state onward"""
        if action_idx == m:
            return 0

        act_type, team = actions[action_idx]

        if act_type == 'p':  # Pick action
            # Try picking each available hero
            results = []
            for i, s in enumerate(available):
                remaining = available[:i] + available[i+1:]

                # If team 1 picks, they gain s; if team 2 picks, team 1 loses s
                current_val = s if team == 1 else -s

                future_val = solve(action_idx + 1, tuple(remaining))
                results.append(current_val + future_val)

            # Team 1 maximizes advantage, Team 2 minimizes it
            if team == 1:
                return max(results)
            else:
                return min(results)
        else:  # Ban action (b)
            # Try banning each available hero
            results = []
            for i in s in enumerate(available):
                remaining = available[:i] + available[i+1:]
                future_val = solve(action_idx + 1, tuple(remaining))
                results.append(future_val)

            # Ban doesn't directly affect current score, but changes future game
            if team == 1:
                return max(results)
            else:
                return min(results)

    result = solve(0, available)
    return str(result)
