def solve(n, k):
    # Special case: if K is 0, any permutation works. Identity is lexicographically smallest.
    if k == 0:
        return ' '.join(str(x) for x in range(1, n + 1))

    # Special case: if N = 1 and K > 0, it's impossible since |P[1] - 1| >= K
    if n == 1 and k > 0:
        return "-1"

    # Try to find the lexicographically smallest permutation using backtracking
    visited = [False] * (n + 1)
    result = [0] * (n + 1)

    def backtrack(pos):
        # Find a valid value for position 'pos'
        # Try values in increasing order to ensure lexicographically smallest
        for val in range(1, n + 1):
            if visited[val]:  # Value already used
                continue

            # Check constraint: abs(val - pos) >= k
            if abs(val - pos) < k:
                continue

            # Use this value
            visited[val] = True
            result[pos] = val

            # Recurse to next position
            if pos == n:
                # All positions filled successfully
                return True
            if backtrack(pos + 1):
                return True

            # Backtrack
            visited[val] = False
            result[pos] = 0

        return False

    if backtrack(1):
        return ' '.join(str(result[i]) for i in range(1, n + 1))
    else:
        return "-1"
