Looking at this problem, I need to:
1. Compute all-pairs shortest path distances (BFS from each node since edges have equal weight = 1)
2. Find 4 distinct cities a→b→c→d that maximize d(a,b) + d(b,c) + d(c,d)

With n ≤ 3000, I'll use BFS preprocessing (O(n(n+m))) and then iterate efficiently over possible paths.

```python
from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)

    # BFS from each node to compute all pairs shortest paths
    dist = [[-1] * (n + 1) for _ in range(n + 1)]

    for start in range(1, n + 1):
        dist[start][start] = 0
        queue = deque([(start, 0)])
        while queue:
            u, d = queue.popleft()
            for v in adj[u]:
                if dist[start][v] == -1:
                    dist[start][v] = d + 1
                    queue.append((v, d + 1))

    max_total = -1
    result = None

    # Try all pairs (b, c) and find best a before b and best d after c
    for b in range(1, n + 1):
        for c in range(1, n + 1):
            # Check if b and c are valid consecutive cities
            if b == c or dist[b][c] == -1 or dist[b][c] == 0:
                continue

            # Find best a: different from b and c, maximizing dist[a][b]
            best_a, max_a_dist = -1, 0
            for a in range(1, n + 1):
                if a == b or a == c or dist[a][b] == -1 or dist[a][b] == 0:
                    continue
                if dist[a][b] > max_a_dist:
                    max_a_dist = dist[a][b]
                    best_a = a

            # Find best d: different from a, b, and c, maximizing dist[c][d]
            best_d, max_d_dist = -1, 0
            for d in range(1, n + 1):
                if d == best_a or d == b or d == c or dist[c][d] == -1 or dist[c][d] == 0:
                    continue
                if dist[c][d] > max_d_dist:
                    max_d_dist = dist[c][d]
                    best_d = d

            # Check if valid quadruple found
            if best_a != -1 and best_d != -1 and best_a != best_d:
                total = max_a_dist + dist[b][c] + max_d_dist
                if total > max_total:
                    max_total = total
                    result = [best_a, b, c, best_d]

    if result is None:
        result = [1, 2, 3, 4]

    return ' '.join(map(str, result))
