def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    attempts = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        s = parts[0]
        c = int(parts[1])
        attempts.append((s, c))

    count = 0

    # Try all 2^n possible codes
    for mask in range(1 << n):
        code = []
        for j in range(n):
            # Bit j=0 is the first character (MSB), j=n-1 is the last character (LSB)
            bit = (mask >> (n - 1 - j)) & 1
            code.append('1' if bit else '0')

        code_str = ''.join(code)

        # Check if this code satisfies all m constraints
        valid = True
        for s, c in attempts:
            matches = 0
            for i in range(n):
                if code_str[i] == s[i]:
                    matches += 1
            if matches != c:
                valid = False
                break

        if valid:
            count += 1

    return str(count)


