    c_divs = get_divisors(m)

    ans = []
    for r in r_divs:
        for c in c_divs:
            if check(r, c):
                ans.append((r, c))

    ans.sort()
    output = [str(len(ans))]
    for r, c in ans:
        output.append(f"! {r} {c}")
    return "\n".join(output)
